"
def transform(grid):
    result = []
    for row in grid:
        new_row = []
        distinct_colors = set(row)
        if len(distinct_colors) > 1:
            rightmost_color = row[-1]
            for val in row:
                if val == rightmost_color:
                    new_row.append(1)
                else:
                    new_row.append(val)
        else:
            new_row = row[:]
        result.append(new_row)
    return result
